class C { n = 1; bump(): number { this.n += 1; return this.n; } }
async function main(): Promise<void> {
  const nat: C[] = [new C()];
  const v: any = nat;
  const j: any = JSON.parse('{"n": 41}');
  v.push(j);
  console.log(nat.length, nat[1].n);
  v[0] = { n: 7 };
  console.log(nat[0].n);
}
